import { useMutation, useQueryClient } from "react-query";
import axios from "axios";

const useCreateRawMaterial = () => {
  const QueryClient = useQueryClient();
  const url = "http://localhost:8080/rawMaterials";

  return useMutation(
    async (obj) => await axios.post(url, obj),
    {
      onSuccess: async () => {
        QueryClient.invalidateQueries("rawMaterialsData");
      },
    },
    {
      onError: async () => {
        console.log("error");
      },
    }
  );
};

export default useCreateRawMaterial;
